// Mezheplerin muteber (fetvaya esas) görüşünü kendi metinlerinde kayda geçiren müteahhir fakihler.
window.MEZHEP_TEMSIL = {
  "Hanefî": { alimler: ["ibnnuceym", "haskefi"], meseleler: ["cem", "abdest", "kurban", "fitre", "ziynet", "nafaka", "kefaet", "uctalak", "teravih", "corap", "hacruhsat", "sahitlik", "faiz", "hilal"] },
  "Hanefî (Ebû Hanîfe)": { alimler: ["ibnnuceym", "haskefi"], meseleler: ["velayet"] },
  "Mâlikî": { alimler: ["halilishak", "derdir"], meseleler: ["cem", "abdest", "fatiha", "kurban", "corap", "fitre", "faiz", "uctalak", "velayet", "kefaet", "hacruhsat", "sahitlik"] },
  "Şâfiî": { alimler: ["remli", "heytemi"], meseleler: ["cem", "abdest", "fatiha", "kurban", "corap", "fitre", "faiz", "uctalak", "teravih", "hilal", "sahitlik"] }
};

// Derinlik katmanını mevcut meselelere yerleştir.
(function () {
  Object.entries(window.MEZHEP_TEMSIL).forEach(([ekol, { alimler, meseleler }]) => meseleler.forEach((id) => {
    const e = (window.MESELE_DERIN2[id] = window.MESELE_DERIN2[id] || {});
    e.alim = e.alim || {};
    e.alim[ekol] = [...(e.alim[ekol] || []), ...alimler];
  }));
  const M = Object.fromEntries(window.MESELELER.map((m) => [m.id, m]));
  const D = window.DERINLIK;
  Object.entries(window.MESELE_DERIN2).forEach(([id, e]) => {
    const m = M[id], d = D[id];
    if (!m || !d) return;
    Object.entries(e.alim || {}).forEach(([ekol, ids]) => {
      const g = m.gorusler.find((x) => x.ekol === ekol);
      if (!g) return;
      g.alimler = g.alimler || [];
      ids.forEach((a) => { if (!g.alimler.includes(a)) g.alimler.push(a); });
    });
    (e.tercih || []).forEach((t) => { if (!d.tercih.some((x) => x.alim === t.alim)) d.tercih.push(t); });
    (e.munakasa || []).forEach((x) => d.munakasa.push(x));
    (e.seyir || []).forEach(({ once, kayit }) => {
      const i = d.seyir.findIndex((s) => s[0] === once);
      if (i < 0) d.seyir.push(kayit); else d.seyir.splice(i, 0, kayit);
    });
    if (e.metin) d.metin = e.metin;
    if (e.uygulama) d.uygulama = e.uygulama;
    const hepsi = [...m.gorusler.flatMap((g) => g.alimler || []), ...d.tercih.map((t) => t.alim)];
    hepsi.forEach((a) => { if (!m.alimler.includes(a) && m.alimler.length < 12) m.alimler.push(a); });
  });
})();
